# tty colors
# generated by rizoo
# note: source this file or run it to apply colors to the Linux TTY.
# only has effect on a real TTY (not a terminal emulator, probably).

if [ "$TERM" = "linux" ]; then
    printf '\e]P0{{ background:hex_raw }}'
    printf '\e]P1{{ error:hex_raw }}'
    printf '\e]P2{{ primary:hex_raw }}'
    printf '\e]P3{{ secondary:hex_raw }}'
    printf '\e]P4{{ tertiary:hex_raw }}'
    printf '\e]P5{{ on_secondary_container:hex_raw }}'
    printf '\e]P6{{ on_primary_container:hex_raw }}'
    printf '\e]P7{{ on_surface:hex_raw }}'
    printf '\e]P8{{ surface_bright:hex_raw }}'
    printf '\e]P9{{ error:hex_raw }}'
    printf '\e]PA{{ primary:hex_raw }}'
    printf '\e]PB{{ secondary:hex_raw }}'
    printf '\e]PC{{ tertiary:hex_raw }}'
    printf '\e]PD{{ on_secondary_container:hex_raw }}'
    printf '\e]PE{{ on_primary_container:hex_raw }}'
    printf '\e]PF{{ on_surface:hex_raw }}'
    clear
fi
